# Regenerate the pinned Temporal/Rust license bundle from Cargo metadata and
# the license files shipped in the crates.io packages.

$ErrorActionPreference = 'Stop'
Set-StrictMode -Version 2

$Root = Split-Path -Parent $PSScriptRoot
$Manifest = Join-Path $Root 'internal\shim\temporal\Cargo.toml'
$OutputDir = Join-Path $Root 'third_party\temporal-licenses'
$Output = Join-Path $OutputDir 'NOTICE.md'

$metadata = (& cargo metadata --format-version 1 --locked --manifest-path $Manifest) | ConvertFrom-Json
if ($LASTEXITCODE -ne 0) { throw 'cargo metadata failed' }

function Find-LicenseFile([string]$Directory, [string]$Kind) {
    $files = @(Get-ChildItem -LiteralPath $Directory -File | Where-Object {
        $_.Name -match '^(LICENSE|COPYING)'
    })
    $match = @($files | Where-Object { $_.Name -match $Kind } | Sort-Object Name | Select-Object -First 1)
    if ($match.Count -gt 0) { return $match[0] }
    $generic = @($files | Where-Object { $_.Name -match '^LICENSE(\.txt)?$' } | Sort-Object Name | Select-Object -First 1)
    if ($generic.Count -gt 0) { return $generic[0] }
    throw "no $Kind license file found in $Directory"
}

$entries = @()
foreach ($package in @($metadata.packages | Where-Object { $null -ne $_.source } | Sort-Object name, version)) {
    $kinds = @()
    if ($package.license -match 'MIT') {
        $kinds += 'MIT'
    } elseif ($package.license -match 'Apache-2\.0') {
        $kinds += 'APACHE'
    }
    if ($package.license -match 'Unicode-3\.0' -and
        (($package.license -match ' AND ') -or ($kinds.Count -eq 0))) {
        $kinds += 'UNICODE'
    }
    if ($kinds.Count -eq 0) {
        throw "unsupported or missing license expression for $($package.name) $($package.version): $($package.license)"
    }
    $directory = Split-Path -Parent $package.manifest_path
    foreach ($kind in $kinds) {
        $file = Find-LicenseFile $directory $kind
        $text = [IO.File]::ReadAllText($file.FullName).Replace("`r`n", "`n").TrimEnd()
        $hashBytes = [Security.Cryptography.SHA256]::Create().ComputeHash([Text.Encoding]::UTF8.GetBytes($text))
        $hash = ([BitConverter]::ToString($hashBytes)).Replace('-', '').ToLowerInvariant()
        $entries += [pscustomobject]@{
            Package = $package.name
            Version = $package.version
            Declared = $package.license
            Kind = $kind
            File = $file.Name
            Hash = $hash
            Text = $text
        }
    }
}

$lines = [Collections.Generic.List[string]]::new()
$lines.Add('# Temporal Rust dependency licenses')
$lines.Add('')
$lines.Add('Generated by `scripts/update_temporal_notices.ps1` from the exact')
$lines.Add('`internal/shim/temporal/Cargo.lock` closure. For `OR` expressions,')
$lines.Add('this distribution selects the MIT alternative when available.')
$lines.Add('')
$lines.Add('| Package | Version | Declared license | Included license |')
$lines.Add('| --- | ---: | --- | --- |')
foreach ($entry in $entries) {
    $lines.Add("| $($entry.Package) | $($entry.Version) | $($entry.Declared) | $($entry.Kind) |")
}

foreach ($group in @($entries | Group-Object Hash | Sort-Object Name)) {
    $first = $group.Group[0]
    $packages = (($group.Group | ForEach-Object { "$($_.Package)@$($_.Version) ($($_.Kind))" }) -join ', ')
    $lines.Add('')
    $lines.Add("## $packages")
    $lines.Add('')
    $lines.Add(('Source license file: `{0}`' -f $first.File))
    $lines.Add('')
    $lines.Add('```text')
    foreach ($line in @($first.Text -split "`n")) { $lines.Add($line) }
    $lines.Add('```')
}

if (-not (Test-Path -LiteralPath $OutputDir)) {
    New-Item -ItemType Directory -Path $OutputDir | Out-Null
}
$rendered = ($lines -join "`n") + "`n"
[IO.File]::WriteAllText($Output, $rendered, [Text.UTF8Encoding]::new($false))
Write-Host "wrote $Output"
